// Package vendor holds the vendoring logic for the minimal Requirement +
// Registry ontology mirror (task #365): banner-stamping the canonical source
// (internal/ontology/canon/requirement.go + registry.go) for copies that
// will live inside a consumer domain's own spec/ Go module, and stripping
// that banner back off for comparison.
//
// This is a DELIBERATELY LEAF package (its only internal import is
// internal/ontology/canon, itself a zero-internal-dependency leaf), the same
// shape as internal/recorder/vendor -- see that package's own doc comment
// for the import-cycle rationale this leaf placement exists to route around
// (cmd/hotam's `vendor-ontology` command WRITES a vendored copy using
// Source, internal/invariants' check_ontology_vendor_current READS a
// vendored copy back and compares it using BodyForHash + StripBanner).
package vendor

import (
	"strings"

	hotamontology "github.com/PHPCraftdream/HotamSpec/internal/ontology/canon"
)

// canonicalRequirementSource / canonicalRegistrySource are the CANONICAL
// sources -- hotamontology.RequirementSource / .RegistrySource, themselves
// go:embed's of internal/ontology/canon's own requirement.go/registry.go,
// frozen at BUILD time. Referencing them here (rather than re-declaring a
// second go:embed of the same files) means there is exactly ONE embed
// directive per file in the whole engine.
var (
	canonicalRequirementSource = hotamontology.RequirementSource
	canonicalRegistrySource    = hotamontology.RegistrySource
	canonicalStakeholderSource = hotamontology.StakeholderSource
)

// Banner is the do-not-edit banner prepended to every vendored copy -- same
// rhetorical shape and same rationale as internal/recorder/vendor.Banner,
// applied here to the ontology mirror instead of the scenario recorder.
const Banner = `// Code generated by ` + "`hotam vendor-ontology`" + `. DO NOT EDIT.
//
// This file is a VENDORED, byte-for-byte copy of HotamSpec's canonical
// internal/ontology/canon source, generated because this spec/ module is a
// SEPARATE Go module from the HotamSpec engine (PLAN-authored-spec-
// discipline.md's own module-boundary decision: an authored domain's spec/
// tree carries its own go.mod so it never depends on the engine's internal/
// packages, and per NEW-2-bis this engine never wires a cross-module
// ` + "`replace`" + ` directive to bridge that gap). Hand-editing this file will be
// silently discarded the next time ` + "`hotam vendor-ontology`" + ` runs, and a hand
// edit that survives until then is exactly what
// check_ontology_vendor_current (internal/invariants) exists to catch: it
// sha256-compares this file's post-banner body against the engine's own
// canon and reports a violation on any drift, whether from a stale
// regeneration or a direct hand edit.
//
// Canonical source: internal/ontology/canon (HotamSpec engine repository).
// See that package's own doc comment for the mirror's design rationale.

`

// RequirementSource returns the full byte-for-byte content this spec/
// module's spec/hotamontology/requirement.go should hold: Banner followed by
// the canonical requirement.go source, unmodified.
func RequirementSource() string {
	return Banner + canonicalRequirementSource
}

// RegistrySource returns the full byte-for-byte content this spec/ module's
// spec/hotamontology/registry.go should hold: Banner followed by the
// canonical registry.go source, unmodified.
func RegistrySource() string {
	return Banner + canonicalRegistrySource
}

// StakeholderSource returns the full byte-for-byte content this spec/
// module's spec/hotamontology/stakeholder.go should hold: Banner followed by
// the canonical stakeholder.go source, unmodified.
func StakeholderSource() string {
	return Banner + canonicalStakeholderSource
}

// StakeholderBodyForHash returns ONLY the canonical stakeholder.go bytes (no
// banner), the text check_ontology_vendor_current hashes.
func StakeholderBodyForHash() string {
	return canonicalStakeholderSource
}

// RequirementBodyForHash returns ONLY the canonical requirement.go bytes (no
// banner), the exact text check_ontology_vendor_current hashes on both sides
// of its comparison.
func RequirementBodyForHash() string {
	return canonicalRequirementSource
}

// RegistryBodyForHash returns ONLY the canonical registry.go bytes (no
// banner), the exact text check_ontology_vendor_current hashes on both sides
// of its comparison.
func RegistryBodyForHash() string {
	return canonicalRegistrySource
}

// StripBanner removes a leading Banner (if present) from src, returning the
// remainder unchanged. Used by check_ontology_vendor_current to recover the
// comparable body from a copy already sitting on disk in a consumer's
// spec/hotamontology/, without needing to re-derive the banner's exact text
// at the call site. Returns src unchanged (ok=false) if src does not start
// with exactly Banner -- e.g. a hand-edited or never-vendored file.
func StripBanner(src string) (body string, ok bool) {
	if !strings.HasPrefix(src, Banner) {
		return src, false
	}
	return strings.TrimPrefix(src, Banner), true
}
